('c2ec9e59-21c4-4a80-adab-6bc677d470a6','MA','a00f00f0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Royal Concierge Ifrane SARL','Royal Concierge Ifrane','tour',4,'verified',ARRAY['en','fr','es','it'],'Private luxury touring service with Mercedes vans, art-historian guides, and exclusive access to private palaces and collections not open to the public.',6.1,96.4,298,3.9,'active'),
('d6f87c58-6734-4498-9214-d2e7201063e1','MA','a00f00f0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Local Eyes Ifrane SARL','Local Eyes Ifrane','guided_experience',1,'verified',ARRAY['en','fr','ary-Latn'],'A collective of young local guides who show you the real city — hidden cafes, street art, and neighborhoods the guidebooks miss. Pay-what-you-want ethos.',5.3,91.2,111,3.7,'active'),
('24c8159c-87e7-4acf-a2df-a486e37e0199','MA','a00f00f0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Insider Morocco SARL','Insider Morocco','guided_experience',3,'verified',ARRAY['en','fr','ar'],'Boutique guiding company pairing you with a dedicated guide for a personalized half-day or full-day experience. We adapt the route to your interests on the fly.',4.4,93,408,4.7,'active'),
('ce92c821-6195-4be2-9f6d-eb0115c5e70c','MA','a00f00f0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Kasbah Storytellers SARL','Kasbah Storytellers','guided_experience',2,'verified',ARRAY['en','fr','ary-Latn'],'Cultural preservation association. Our guides are retired teachers and historians who share oral traditions, folklore, and stories passed down for generations.',7.7,98.2,308,4.7,'active'),
('f90e5125-5457-450c-a376-14d025cc8d70','MA','a00f00f0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Riad Ifrane Budget SARL','Riad Ifrane Budget','stay',1,'verified',ARRAY['en','fr'],'A clean, friendly guesthouse in the heart of the medina. Shared bathrooms, rooftop terrace, and free mint tea. Perfect for backpackers and solo travelers.',6,93.1,385,4.1,'active'),
('19f01f8a-2394-45da-b6a6-30f754a3a2de','MA','a00f00f0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Dar Ifrane Boutique SARL','Dar Ifrane Boutique','stay',3,'verified',ARRAY['en','fr','es'],'A beautifully restored 19th-century riad with 8 rooms, each uniquely decorated with antiques and local textiles. Plunge pool, hammam, and breakfast on the rooftop.',8.3,96.2,341,4,'active'),
('7dc3de50-9550-4d1d-94bb-d6e389a362ed','MA','a00f00f0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Palais Ifrane Royal SARL','Palais Ifrane Royal','stay',4,'verified',ARRAY['en','fr','it','de'],'A former palace converted into an all-suite luxury hotel. Private butlers, Michelin-trained chef, spa, and curated excursions. The finest address in the city.',8.4,95.6,301,4.4,'active'),
('f2261e38-5b3d-4d34-95f3-fb649f78460f','MA','a00f00f0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Street Food Ifrane Tours SARL','Street Food Ifrane Tours','meal',1,'verified',ARRAY['en','fr','ary-Latn'],'We take you through the best food stalls and hidden corners of the medina. 6+ tastings, from bissara to snail soup. Come hungry!',4.5,92.6,204,3.7,'active'),
('506714ca-31da-4a6c-973f-f9a618195034','MA','a00f00f0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Table Ifrane Family Kitchen SARL','Table Ifrane Family Kitchen','meal',2,'verified',ARRAY['en','fr','ary-Latn'],'A Moroccan family welcomes you into their home for a traditional 3-course dinner. Couscous on Fridays, tagine every day. Recipes passed down four generations.',6.8,89,102,4,'active'),
('cf0e3225-e4e8-463e-a815-b2b8fcefb464','MA','a00f00f0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Le Salon Ifrane SARL','Le Salon Ifrane','meal',4,'verified',ARRAY['en','fr'],'Fine dining in an elegant riad setting. Modern Moroccan cuisine by a chef trained in Paris and Marrakech. Wine pairing available. Reservation required.',11,92,413,4.8,'active'),
('ed672426-8e4e-4675-bbce-2f3d698f3e33','MA','a00f00f0-aaaa-aaaa-aaaa-aaaaaaaaaaaa','Ifrane Adventure Club SARL','Ifrane Adventure Club','activity',2,'verified',ARRAY['en','fr','ar'],'A local outdoor club offering hiking, cycling, and climbing for all levels. Certified guides, quality equipment, and a passion for sharing Morocco''s natural beauty.',4.7,88.2,375,4.9,'active'),
